"""Exporter for the Arduino header format.

Writes a .h file that the player sketch includes directly as song.h.
"""

from pathlib import Path
from typing import List, Optional

from .music_types import ArduinoNoteEvent


HEADER_TOP = """\
// Auto-generated by midi_converter. Do not edit manually.
// Compatible with the StepperVoice engine in bridge/sketches/player.

#pragma once

#include <Arduino.h>

#ifndef STEPPER_NOTE_EVENT_DEFINED
#define STEPPER_NOTE_EVENT_DEFINED
struct NoteEvent {
    float frequency;
    uint16_t durationMs;
};
#endif
"""


def _format_voice(name: str, events: List[ArduinoNoteEvent]) -> str:
    lines = [f"const NoteEvent {name}[] PROGMEM = {{"]
    for e in events:
        # uint16_t limit: 65535 ms, about 65 s per note.
        dur = min(max(e.duration_ms, 0), 65535)
        lines.append(f"    {{{e.frequency:.2f}f, {dur}}},")
    lines.append("};")
    lines.append(f"const unsigned int {name}Length = {len(events)};")
    return "\n".join(lines)


def export_song_header(
    path: str,
    voice1: List[ArduinoNoteEvent],
    voice2: List[ArduinoNoteEvent],
    voice3: List[ArduinoNoteEvent],
    voice4: List[ArduinoNoteEvent],
    song_name: Optional[str] = None,
    source_file: Optional[str] = None,
    metadata: Optional[dict] = None,
) -> None:
    parts = [HEADER_TOP]
    if song_name:
        parts.append(f"// Song: {song_name}")
    if source_file:
        parts.append(f"// Source MIDI: {source_file}")
    if metadata:
        for k, v in metadata.items():
            parts.append(f"// {k}: {v}")
    parts.append("")
    parts.append(_format_voice("voice1", voice1))
    parts.append("")
    parts.append(_format_voice("voice2", voice2))
    parts.append("")
    parts.append(_format_voice("voice3", voice3))
    parts.append("")
    parts.append(_format_voice("voice4", voice4))
    parts.append("")

    # Size note as a comment, useful for the flash budget on the UNO.
    bytes_per_event = 6  # float + uint16, no padding on AVR
    total_events = len(voice1) + len(voice2) + len(voice3) + len(voice4)
    parts.append(f"// total events: {total_events} ({total_events * bytes_per_event} bytes in PROGMEM)")

    Path(path).parent.mkdir(parents=True, exist_ok=True)
    with open(path, "w") as f:
        f.write("\n".join(parts))
